    | StructuredWriter_Sep((struct( pre, sep, post )), differentLines, items) ->
        let seperator: StringRope =
            if differentLines then
                String_append (StringRopeOne "\n") (String_append (StructuredWriter_asIndent indent__) sep)

            else
                sep
        
        String_concat
            [ pre;
              String_join seperator (List.map ((>>) id (StructuredWriter_writeIndented indent__)) items);
              post
            ]

    | StructuredWriter_Breaked(items) ->
        String_join (String_append (StringRopeOne "\n") (StructuredWriter_asIndent indent__)) (List.collect ((>>) (StructuredWriter_writeIndented 0L) (String_split (StringRopeOne "\n"))) items)

    | StructuredWriter_Str(s) ->
        s

    | StructuredWriter_Indent(n, next) ->
        String_append (StructuredWriter_asIndent ((+) n indent__)) (StructuredWriter_writeIndented ((+) n indent__) next)

    | StructuredWriter_Spaced(items) ->
        String_join (StringRopeOne " ") (List.map (StructuredWriter_writeIndented indent__) items)

    | StructuredWriter_Joined(items) ->
        String_concat (List.map (StructuredWriter_writeIndented indent__) items)

    | StructuredWriter_Append(x, y) ->
        String_append (StructuredWriter_writeIndented indent__ x) (StructuredWriter_writeIndented indent__ y)

