let rec Print_lineSpreadWithRemaining (print: Print_Print) (remainingPrints: List<Print_Print>) : Print_LineSpread =
    match print with
    | Print_Exact(_, _) ->
        match remainingPrints with
        | [] ->
            Print_SingleLine

        | nextPrint :: nextRemainingPrints ->
            Print_lineSpreadWithRemaining nextPrint nextRemainingPrints

    | Print_FollowedBy(b, a) ->
        Print_lineSpreadWithRemaining a (List_cons b remainingPrints)

    | Print_Linebreak(_, _) ->
        Print_MultipleLines

    | Print_LinebreakIndented(_, _) ->
        Print_MultipleLines

    | Print_WithIndentIncreasedBy(_, innerPrint) ->
        Print_lineSpreadWithRemaining innerPrint remainingPrints

    | Print_WithIndentAtNextMultipleOf4(innerPrint, _) ->
        Print_lineSpreadWithRemaining innerPrint remainingPrints

