    | Print_WithIndentIncreasedBy(increase, innerPrint) ->
        Print_toStringWithIndentAndLinebreakIndentAsStringWithRight ((+) ((+) indentIgnoringMultiplesOfBy4 increase) 0L) (String_append linebreakIndentAsString (Print_indentAtMost4 increase)) right innerPrint

