let rec Internal_unconsBiggestWhileDroppingGT
    (compareKey: 'comparable)
    (queue: List<Internal_InnerDict<'comparable, 'v>>)
    : ValueOption<
        (struct(
          'comparable
        * 'v
        * Internal_VisitQueue<'comparable, 'v>
        ))
        > =
    match queue with
    | [] ->
        ValueNone

    | h :: t ->
        match h with
        | Internal_InnerNode(color, key, value, childLT, childGT) ->
            if (>) key compareKey then
                Internal_unconsBiggestWhileDroppingGT compareKey (List_cons childLT t)

            else
                if Basics_eq key compareKey then
                    (fun (generated_0:
                            (struct(
                              'comparable
                            * 'v
                            * List<Internal_InnerDict<'comparable, 'v>>
                            ))
                         ) ->
                        ValueSome generated_0
                    )
                        (struct( key, value, List_cons childLT t ))

                else
                    match childGT with
                    | Internal_Leaf ->
                        (fun (generated_0:
                                (struct(
                                  'comparable
                                * 'v
                                * List<Internal_InnerDict<'comparable, 'v>>
                                ))
                             ) ->
                            ValueSome generated_0
                        )
                            (struct( key, value, List_cons childLT t ))

                    | _ ->
                        Internal_unconsBiggestWhileDroppingGT
                            compareKey
                            (List_cons
                                childGT
                                (List_cons
                                    ((fun (generated_0: Internal_NColor) (generated_1: 'comparable) (generated_2: 'v) (generated_3: Internal_InnerDict<'comparable, 'v>) (generated_4: Internal_InnerDict<'comparable, 'v>) ->
                                        Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                                     )
                                        color
                                        key
                                        value
                                        childLT
                                        Internal_Leaf
                                    )
                                    t
                                )
                            )

        | Internal_Leaf ->
            Internal_unconsBiggestWhileDroppingGT compareKey t

