let rec Union_unwrap
    (vacc:
        ValueOption<
            (struct(
              'comparable
            * 'v
            * Internal_VisitQueue<'comparable, 'v>
            ))
            >
    )
    (dacc:
        ListWithLength_ListWithLength<
            (struct(
              'comparable
            * 'v
            ))
            >
    )
    : ListWithLength_ListWithLength<
        (struct(
          'comparable
        * 'v
        ))
        > =
    match vacc with
    | ValueNone ->
        dacc

    | ValueSome((struct( key, value, rest ))) ->
        Union_unwrap (Internal_unconsBiggest rest) (ListWithLength_cons (struct( key, value )) dacc)

let rec Union_unionFromZipper
    (dacc:
        ListWithLength_ListWithLength<
            (struct(
              'comparable
            * 'v
            ))
            >
    )
    (lleft:
        ValueOption<
            (struct(
              'comparable
            * 'v
            * Internal_VisitQueue<'comparable, 'v>
            ))
            >
    )
    (rleft:
        ValueOption<
            (struct(
              'comparable
            * 'v
            * Internal_VisitQueue<'comparable, 'v>
            ))
            >
    )
    : ListWithLength_ListWithLength<
        (struct(
          'comparable
        * 'v
        ))
        > =
    match lleft with
    | ValueNone ->
        Union_unwrap rleft dacc

    | ValueSome((struct( lkey, lvalue, ltail ))) ->
        match rleft with
        | ValueNone ->
            Union_unwrap lleft dacc

        | ValueSome((struct( rkey, rvalue, rtail ))) ->
            if (>) lkey rkey then
                Union_unionFromZipper (ListWithLength_cons (struct( lkey, lvalue )) dacc) (Internal_unconsBiggest ltail) rleft

            else
                if (>) rkey lkey then
                    Union_unionFromZipper (ListWithLength_cons (struct( rkey, rvalue )) dacc) lleft (Internal_unconsBiggest rtail)

                else
                    Union_unionFromZipper (ListWithLength_cons (struct( lkey, lvalue )) dacc) (Internal_unconsBiggest ltail) (Internal_unconsBiggest rtail)

let Internal_setRootBlack (dict: Internal_InnerDict<'k, 'v>) : Internal_InnerDict<'k, 'v> =
    match dict with
    | Internal_InnerNode(Internal_Red, k, v, l, r) ->
        (fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
            Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
        )
            Internal_Black
            k
            v
