let Internal_fromSortedList
    (dacc:
        ListWithLength_ListWithLength<
            (struct(
              'comparable
            * 'v
            ))
            >
    )
    : Internal_Dict<'comparable, 'v> =
    let len: int64 =
        ListWithLength_length dacc
    
    let redLayer: int64 =
        Basics_floor (Basics_logBase 2.0 (float len))
    
    let rec go
        (layer: int64)
        (fromIncluded: int64)
        (toExcluded: int64)
        (acc:
            List<
                (struct(
                  'comparable1
                * 'v1
                ))
                >
        )
        : (struct(
            Internal_InnerDict<'comparable1, 'v1>
          * List<
                (struct(
                  'comparable1
                * 'v1
                ))
                >
          )) =
        if (>=) fromIncluded toExcluded then
            (struct( Internal_Leaf, acc ))

        else
            let mid: int64 =
                (+) fromIncluded ((/) ((-) toExcluded fromIncluded) 2L)
            
            let ((struct( lchild, accAfterLeft )):
                    (struct(
                      Internal_InnerDict<'comparable1, 'v1>
                    * List<
                        (struct(
                          'comparable1
                        * 'v1
                        ))
                        >
                    ))
                ) =
                go ((+) layer 1L) fromIncluded mid acc
            
            match accAfterLeft with
            | [] ->
                (struct( Internal_Leaf, acc ))

            | (struct( k, v )) :: tail ->
                let color: Internal_NColor =
                    if Basics_and ((>) layer 0L) (Basics_eq layer redLayer) then
                        Internal_Red

                    else
                        Internal_Black
                
                let ((struct( rchild, accAfterRight )):
                        (struct(
                          Internal_InnerDict<'comparable1, 'v1>
                        * List<
                            (struct(
                              'comparable1
                            * 'v1
                            ))
                            >
                        ))
                    ) =
                    go ((+) layer 1L) ((+) mid 1L) toExcluded tail
                
                (struct(
                  (fun (generated_0: Internal_NColor) (generated_1: 'comparable1) (generated_2: 'v1) (generated_3: Internal_InnerDict<'comparable1, 'v1>) (generated_4: Internal_InnerDict<'comparable1, 'v1>) ->
                    Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                  )
                    color
                    k
                    v
                    lchild
                    rchild
                , accAfterRight
                ))
    (fun (generated_0: int64) (generated_1: Internal_InnerDict<'comparable, 'v>) ->
        Internal_Dict (struct( generated_0, generated_1 ))
    )
        len
        (Tuple_first (go 0L 0L len (ListWithLength_toList dacc)))

let Union_union ((Internal_Dict(sz1, t1) as d1): Internal_Dict<'comparable, 'v>) ((Internal_Dict(sz2, t2) as d2): Internal_Dict<'comparable, 'v>) : Internal_Dict<'comparable, 'v> =
    if Basics_eq sz1 0L then
        d2

    else
        if Basics_eq sz2 0L then
            d1

        else
            Internal_fromSortedList (Union_unionFromZipper ListWithLength_empty (Internal_unconsBiggest [ t1 ]) (Internal_unconsBiggest [ t2 ]))

