                    Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                 )
                    Internal_Black
                    llK
                    llV
                    llLeft
                    llRight
                )
                ((fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                    Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                 )
                    Internal_Black
                    key
                    value
                    lRight
                    right
                )

        | _ ->
            (fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
