let rec Internal_insertHelpNoReplace (key: 'comparable) (value: 'v) (dict: Internal_InnerDict<'comparable, 'v>) : ValueOption<Internal_InnerDict<'comparable, 'v>> =
    match dict with
    | Internal_Leaf ->
        (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
            ValueSome generated_0
        )
            ((fun (generated_0: Internal_NColor) (generated_1: 'comparable) (generated_2: 'v) (generated_3: Internal_InnerDict<'comparable, 'v>) (generated_4: Internal_InnerDict<'comparable, 'v>) ->
                Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
             )
                Internal_Red
                key
                value
                Internal_Leaf
                Internal_Leaf
            )

    | Internal_InnerNode(nColor, nKey, nValue, nLeft, nRight) ->
        match Basics_compare key nKey with
        | Basics_Order.LT ->
            match Internal_insertHelpNoReplace key value nLeft with
            | ValueSome(newLeft) ->
                (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
                    ValueSome generated_0
                )
                    (Internal_balance nColor nKey nValue newLeft nRight)

            | ValueNone ->
                ValueNone

        | Basics_Order.EQ ->
            ValueNone

        | Basics_Order.GT ->
            match Internal_insertHelpNoReplace key value nRight with
            | ValueSome(newRight) ->
                (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
                    ValueSome generated_0
                )
                    (Internal_balance nColor nKey nValue nLeft newRight)

            | ValueNone ->
                ValueNone

let Internal_insertNoReplace (key: 'comparable) (value: 'v) ((Internal_Dict(sz, dict) as orig): Internal_Dict<'comparable, 'v>) : Internal_Dict<'comparable, 'v> =
