    | ValueSome(result) ->
        (fun (generated_0: int64) (generated_1: Internal_InnerDict<'comparable, 'v>) ->
            Internal_Dict (struct( generated_0, generated_1 ))
        )
            ((+) sz 1L)
            (Internal_setRootBlack result)

    | ValueNone ->
        orig

let rec Hex_unsafeToDigit (num: int64) : int =
    match num with
    | 0L ->
        48

    | 1L ->
        49

    | 2L ->
        50

    | 3L ->
        51

    | 4L ->
        52

    | 5L ->
        53

    | 6L ->
        54

    | 7L ->
        55

    | 8L ->
        56

    | 9L ->
        57

    | 10L ->
        97

    | 11L ->
        98

    | 12L ->
        99

    | 13L ->
        100

    | 14L ->
        101

    | 15L ->
        102

    | _ ->
        Hex_unsafeToDigit num

let rec Hex_unsafePositiveToDigits (digits: List<int>) (num: int64) : List<int> =
    if (<) num 16L then
        List_cons (Hex_unsafeToDigit num) digits

    else
        Hex_unsafePositiveToDigits (List_cons (Hex_unsafeToDigit (Basics_modBy 16L num)) digits) ((/) num 16L)

let Hex_toString (num: int64) : StringRope =
    String_fromList
        (if (<) num 0L then
            List_cons 45 (Hex_unsafePositiveToDigits [] (Basics_inegate num))

         else
            Hex_unsafePositiveToDigits [] num
        )

let rec Hex_fromStringHelp (position: int64) (chars: List<int>) (accumulated: int64) : Result_Result<StringRope, int64> =
    match chars with
    | [] ->
        (fun (generated_0: int64) ->
            Ok generated_0
        )
            accumulated

    | char_ :: rest ->
        match char_ with
        | 48 ->
            Hex_fromStringHelp ((-) position 1L) rest accumulated

        | 49 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated (Basics_ipow 16L position))

        | 50 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 2L (Basics_ipow 16L position)))

        | 51 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 3L (Basics_ipow 16L position)))

        | 52 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 4L (Basics_ipow 16L position)))

        | 53 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 5L (Basics_ipow 16L position)))

        | 54 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 6L (Basics_ipow 16L position)))

        | 55 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 7L (Basics_ipow 16L position)))

        | 56 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 8L (Basics_ipow 16L position)))

        | 57 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 9L (Basics_ipow 16L position)))

        | 97 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 10L (Basics_ipow 16L position)))

        | 98 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 11L (Basics_ipow 16L position)))

        | 99 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 12L (Basics_ipow 16L position)))

        | 100 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 13L (Basics_ipow 16L position)))

        | 101 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 14L (Basics_ipow 16L position)))

        | 102 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 15L (Basics_ipow 16L position)))

        | nonHex ->
            (fun (generated_0: StringRope) ->
                Error generated_0
            )
                (String_append (String_fromChar nonHex) (StringRopeOne " is not a valid hexadecimal character."))

let Hex_fromString (str: StringRope) : Result_Result<StringRope, int64> =
    if String_isEmpty str then
        (fun (generated_0: StringRope) ->
            Error generated_0
        )
            (StringRopeOne "Empty strings are not valid hexadecimal strings.")

    else
        let result: Result_Result<StringRope, int64> =
            if String_startsWith (StringRopeOne "-") str then
                let list_: List<int> =
                    ValueOption.defaultValue [] (List_tail (String_toList str))
                
                Result.map Basics_inegate (Hex_fromStringHelp ((-) (List_length list_) 1L) list_ 0L)

            else
                Hex_fromStringHelp ((-) (String_length str) 1L) (String_toList str) 0L
        
        let formatError (err: StringRope) : StringRope =
            String_join
                (StringRopeOne " ")
                [ String_append (StringRopeOne "\"") (String_append str (StringRopeOne "\""));
                  StringRopeOne "is not a valid hexadecimal string because";
                  err
                ]
        
        Result.mapError formatError result

