let rec FastDict_stoppableFoldrInner (func: 'k -> 'v -> 'acc -> FastDict_Step<'acc>) (acc: 'acc) (dict: Internal_InnerDict<'k, 'v>) : FastDict_Step<'acc> =
    match dict with
    | Internal_Leaf ->
        (fun (generated_0: 'acc) ->
            FastDict_Continue generated_0
        )
            acc

    | Internal_InnerNode(_, key, value, left, right) ->
        match FastDict_stoppableFoldrInner func acc right with
        | FastDict_Continue(racc) ->
            match func key value racc with
            | FastDict_Continue(vacc) ->
                FastDict_stoppableFoldrInner func vacc left

            | FastDict_Stop(vacc) ->
                (fun (generated_0: 'acc) ->
                    FastDict_Stop generated_0
                )
                    vacc

        | FastDict_Stop(lacc) ->
            (fun (generated_0: 'acc) ->
                FastDict_Stop generated_0
            )
                lacc

let FastDict_stoppableFoldr (func: 'k -> 'v -> 'acc -> FastDict_Step<'acc>) (acc: 'acc) (Internal_Dict(_, dict): Internal_Dict<'k, 'v>) : 'acc =
    match FastDict_stoppableFoldrInner func acc dict with
    | FastDict_Continue(res) ->
        res

    | FastDict_Stop(res) ->
        res

