let rec FastDict_restructureInner (leafFunc: 'acc) (nodeFunc: Generated_Key_Left_Right_Value<'key, unit -> 'acc, unit -> 'acc, 'value> -> 'acc) (dict: Internal_InnerDict<'key, 'value>) : 'acc =
    match dict with
    | Internal_Leaf ->
        leafFunc

    | Internal_InnerNode(_, key, value, left, right) ->
        nodeFunc
            { Key = key
            ; Left =
                fun (_: unit) ->
                    FastDict_restructureInner leafFunc nodeFunc left
            ; Right =
                fun (_: unit) ->
                    FastDict_restructureInner leafFunc nodeFunc right
            ; Value = value
            }

