let FastDict_removeHelpPrepEQGT (dict: Internal_InnerDict<'comparable, 'v>) (color: Internal_NColor) (key: 'comparable) (value: 'v) (left: Internal_InnerDict<'comparable, 'v>) (right: Internal_InnerDict<'comparable, 'v>) : Internal_InnerDict<'comparable, 'v> =
    match left with
    | Internal_InnerNode(Internal_Red, lK, lV, lLeft, lRight) ->
        (fun (generated_0: Internal_NColor) (generated_1: 'comparable) (generated_2: 'v) (generated_3: Internal_InnerDict<'comparable, 'v>) (generated_4: Internal_InnerDict<'comparable, 'v>) ->
            Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
        )
            color
            lK
            lV
            lLeft
            ((fun (generated_0: Internal_NColor) (generated_1: 'comparable) (generated_2: 'v) (generated_3: Internal_InnerDict<'comparable, 'v>) (generated_4: Internal_InnerDict<'comparable, 'v>) ->
                Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
             )
                Internal_Red
                key
                value
                lRight
                right
            )

    | Internal_InnerNode(Internal_Black, lK, lV, lLeft, lRight) ->
        match right with
        | Internal_InnerNode(Internal_Black, rK, rV, (Internal_InnerNode(Internal_Black, _, _, _, _) as rLeft), rRight) ->
            FastDict_moveRedRight key value lK lV lLeft lRight rK rV rLeft rRight

        | Internal_InnerNode(Internal_Black, rK, rV, Internal_Leaf, rRight) ->
            FastDict_moveRedRight key value lK lV lLeft lRight rK rV Internal_Leaf rRight

        | _ ->
            dict

    | Internal_Leaf ->
        dict

let FastDict_moveRedLeft (clr: Internal_NColor) (k: 'k) (v: 'v) (left: Internal_InnerDict<'k, 'v>) (right: Internal_InnerDict<'k, 'v>) : Generated_Color_K_Left_Right_V<Internal_NColor, 'k, Internal_InnerDict<'k, 'v>, Internal_InnerDict<'k, 'v>, 'v> =
    match left with
    | Internal_InnerNode(_, lK, lV, lLeft, lRight) ->
        match right with
        | Internal_InnerNode(_, rK, rV, Internal_InnerNode(Internal_Red, rlK, rlV, rlL, rlR), rRight) ->
            { Color = Internal_Red
            ; K = rlK
            ; Left =
                (fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                    Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                )
                    Internal_Black
                    k
                    v
                    ((fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                        Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                     )
                        Internal_Red
                        lK
                        lV
                        lLeft
                        lRight
                    )
                    rlL
            ; Right =
                (fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                    Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                )
                    Internal_Black
                    rK
                    rV
                    rlR
                    rRight
            ; V = rlV
            }

        | Internal_InnerNode(_, rK, rV, rLeft, rRight) ->
            { Color = Internal_Black
            ; K = k
            ; Left =
                (fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                    Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                )
                    Internal_Red
                    lK
                    lV
                    lLeft
                    lRight
            ; Right =
                (fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                    Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                )
                    Internal_Red
                    rK
                    rV
                    rLeft
                    rRight
            ; V = v
            }

        | _ ->
            { Color = clr
            ; K = k
            ; Left = left
            ; Right = right
            ; V = v
            }

    | _ ->
        { Color = clr
        ; K = k
        ; Left = left
        ; Right = right
        ; V = v
        }

let rec FastDict_removeMin (dict: Internal_InnerDict<'k, 'v>) : Internal_InnerDict<'k, 'v> =
    match dict with
    | Internal_InnerNode(color, key, value, (Internal_InnerNode(lColor, _, _, lLeft, _) as left), right) ->
        match lColor with
        | Internal_Black ->
            match lLeft with
            | Internal_InnerNode(Internal_Red, _, _, _, _) ->
                (fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                    Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                )
                    color
                    key
                    value
                    (FastDict_removeMin left)
                    right

            | _ ->
                let res: Generated_Color_K_Left_Right_V<Internal_NColor, 'k, Internal_InnerDict<'k, 'v>, Internal_InnerDict<'k, 'v>, 'v> =
                    FastDict_moveRedLeft color key value left right
                
                Internal_balance res.Color res.K res.V (FastDict_removeMin res.Left) res.Right

        | _ ->
            (fun (generated_0: Internal_NColor) (generated_1: 'k) (generated_2: 'v) (generated_3: Internal_InnerDict<'k, 'v>) (generated_4: Internal_InnerDict<'k, 'v>) ->
                Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
            )
                color
                key
                value
                (FastDict_removeMin left)
                right

    | _ ->
        Internal_Leaf

