let rec FastDict_intersectFromZipper
    (dacc:
        ListWithLength_ListWithLength<
            (struct(
              'comparable
            * 'v
            ))
            >
    )
    (lleft:
        ValueOption<
            (struct(
              'comparable
            * 'v
            * Internal_VisitQueue<'comparable, 'v>
            ))
            >
    )
    (rleft:
        ValueOption<
            (struct(
              'comparable
            * 'v
            * Internal_VisitQueue<'comparable, 'v>
            ))
            >
    )
    : ListWithLength_ListWithLength<
        (struct(
          'comparable
        * 'v
        ))
        > =
    match lleft with
    | ValueNone ->
        dacc

    | ValueSome((struct( lkey, lvalue, ltail ))) ->
        match rleft with
        | ValueNone ->
            dacc

        | ValueSome((struct( rkey, _, rtail ))) ->
            if (>) lkey rkey then
                FastDict_intersectFromZipper dacc (Internal_unconsBiggestWhileDroppingGT rkey ltail) rleft

            else
                if (>) rkey lkey then
                    FastDict_intersectFromZipper dacc lleft (Internal_unconsBiggestWhileDroppingGT lkey rtail)

                else
                    FastDict_intersectFromZipper (ListWithLength_cons (struct( lkey, lvalue )) dacc) (Internal_unconsBiggest ltail) (Internal_unconsBiggest rtail)

let rec FastDict_insertHelp
    (key: 'comparable)
    (value: 'v)
    (dict: Internal_InnerDict<'comparable, 'v>)
    : (struct(
        Internal_InnerDict<'comparable, 'v>
      * bool
      )) =
    match dict with
    | Internal_Leaf ->
        (struct(
          (fun (generated_0: Internal_NColor) (generated_1: 'comparable) (generated_2: 'v) (generated_3: Internal_InnerDict<'comparable, 'v>) (generated_4: Internal_InnerDict<'comparable, 'v>) ->
            Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
          )
            Internal_Red
            key
            value
            Internal_Leaf
            Internal_Leaf
        , true
        ))

    | Internal_InnerNode(nColor, nKey, nValue, nLeft, nRight) ->
        match Basics_compare key nKey with
        | Basics_Order.LT ->
            let ((struct( newLeft, isNew )):
                    (struct(
                      Internal_InnerDict<'comparable, 'v>
                    * bool
                    ))
                ) =
                FastDict_insertHelp key value nLeft
            
            (struct( Internal_balance nColor nKey nValue newLeft nRight, isNew ))

        | Basics_Order.EQ ->
            (struct(
              (fun (generated_0: Internal_NColor) (generated_1: 'comparable) (generated_2: 'v) (generated_3: Internal_InnerDict<'comparable, 'v>) (generated_4: Internal_InnerDict<'comparable, 'v>) ->
                Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
              )
                nColor
                nKey
                value
                nLeft
                nRight
            , false
            ))

        | Basics_Order.GT ->
            let ((struct( newRight, isNew )):
                    (struct(
                      Internal_InnerDict<'comparable, 'v>
                    * bool
                    ))
                ) =
                FastDict_insertHelp key value nRight
            
            (struct( Internal_balance nColor nKey nValue nLeft newRight, isNew ))

let FastDict_insertInner
    (key: 'comparable)
    (value: 'v)
    (dict: Internal_InnerDict<'comparable, 'v>)
