let FastDict_insert (key: 'comparable) (value: 'v) (Internal_Dict(sz, dict): Internal_Dict<'comparable, 'v>) : Internal_Dict<'comparable, 'v> =
    let ((struct( result, isNew )):
            (struct(
              Internal_InnerDict<'comparable, 'v>
            * bool
            ))
