    if isNew then
        (fun (generated_0: int64) (generated_1: Internal_InnerDict<'comparable, 'v>) ->
            Internal_Dict (struct( generated_0, generated_1 ))
        )
            ((+) sz 1L)
            result

    else
        (fun (generated_0: int64) (generated_1: Internal_InnerDict<'comparable, 'v>) ->
            Internal_Dict (struct( generated_0, generated_1 ))
        )
            sz
            result

let rec Graph_fastDictRangeToConstantInto (list_: FastDict_Dict<int64, 'a>) (startInclusive: int64) (endInclusive: int64) (constantValue: 'a) : FastDict_Dict<int64, 'a> =
    if (<=) startInclusive endInclusive then
        Graph_fastDictRangeToConstantInto (FastDict_insert endInclusive constantValue list_) startInclusive ((-) endInclusive 1L) constantValue

    else
        list_

let FastDict_getMinKey (Internal_Dict(_, dict): Internal_Dict<'k, 'v>) : ValueOption<'k> =
    let rec go (n: Internal_InnerDict<'k1, 'v1>) : ValueOption<'k1> =
        match n with
        | Internal_Leaf ->
            ValueNone

        | Internal_InnerNode(_, k, _, Internal_Leaf, _) ->
            (fun (generated_0: 'k1) ->
                ValueSome generated_0
            )
                k

        | Internal_InnerNode(_, _, _, l, _) ->
            go l
    go dict

