let rec FastDict_removeHelpEQGT (targetKey: 'comparable) (dict: Internal_InnerDict<'comparable, 'v>) : ValueOption<Internal_InnerDict<'comparable, 'v>> =
    match dict with
    | Internal_InnerNode(color, key, value, left, right) ->
        if Basics_eq targetKey key then
            match FastDict_getMinInner right with
            | ValueSome((struct( minKey, minValue ))) ->
                (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
                    ValueSome generated_0
                )
                    (Internal_balance color minKey minValue left (FastDict_removeMin right))

            | ValueNone ->
                (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
                    ValueSome generated_0
                )
                    Internal_Leaf

        else
            match FastDict_removeHelp targetKey right with
            | ValueSome(newRight) ->
                (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
                    ValueSome generated_0
                )
                    (Internal_balance color key value left newRight)

            | ValueNone ->
                ValueNone

    | Internal_Leaf ->
        ValueNone

and FastDict_removeHelp (targetKey: 'comparable) (dict: Internal_InnerDict<'comparable, 'v>) : ValueOption<Internal_InnerDict<'comparable, 'v>> =
    match dict with
    | Internal_Leaf ->
        ValueNone

    | Internal_InnerNode(color, key, value, left, right) ->
        if (<) targetKey key then
            match left with
            | Internal_InnerNode(Internal_Black, _, _, lLeft, _) ->
                match lLeft with
                | Internal_InnerNode(Internal_Red, _, _, _, _) ->
                    match FastDict_removeHelp targetKey left with
                    | ValueSome(newLeft) ->
                        (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
                            ValueSome generated_0
                        )
                            ((fun (generated_0: Internal_NColor) (generated_1: 'comparable) (generated_2: 'v) (generated_3: Internal_InnerDict<'comparable, 'v>) (generated_4: Internal_InnerDict<'comparable, 'v>) ->
                                Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                             )
                                color
                                key
                                value
                                newLeft
                                right
                            )

                    | ValueNone ->
                        ValueNone

                | _ ->
                    let res: Generated_Color_K_Left_Right_V<Internal_NColor, 'comparable, Internal_InnerDict<'comparable, 'v>, Internal_InnerDict<'comparable, 'v>, 'v> =
                        FastDict_moveRedLeft color key value left right
                    
                    match FastDict_removeHelp targetKey res.Left with
                    | ValueSome(newLeft) ->
                        (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
                            ValueSome generated_0
                        )
                            (Internal_balance res.Color res.K res.V newLeft res.Right)

                    | ValueNone ->
                        ValueNone

            | _ ->
                match FastDict_removeHelp targetKey left with
                | ValueSome(newLeft) ->
                    (fun (generated_0: Internal_InnerDict<'comparable, 'v>) ->
                        ValueSome generated_0
                    )
                        ((fun (generated_0: Internal_NColor) (generated_1: 'comparable) (generated_2: 'v) (generated_3: Internal_InnerDict<'comparable, 'v>) (generated_4: Internal_InnerDict<'comparable, 'v>) ->
                            Internal_InnerNode (struct( generated_0, generated_1, generated_2, generated_3, generated_4 ))
                         )
                            color
                            key
                            value
                            newLeft
                            right
                        )

                | ValueNone ->
                    ValueNone

        else
            FastDict_removeHelpEQGT targetKey (FastDict_removeHelpPrepEQGT dict color key value left right)

let FastDict_remove (key: 'comparable) ((Internal_Dict(sz, dict) as orig): Internal_Dict<'comparable, 'v>) : Internal_Dict<'comparable, 'v> =
    match FastDict_removeHelp key dict with
    | ValueSome(result) ->
        (fun (generated_0: int64) (generated_1: Internal_InnerDict<'comparable, 'v>) ->
            Internal_Dict (struct( generated_0, generated_1 ))
        )
            ((-) sz 1L)
            (Internal_setRootBlack result)

    | ValueNone ->
        orig

