        | Basics_Order.LT ->
            FastDict_getInner targetKey left

        | Basics_Order.EQ ->
            (fun (generated_0: 'v) ->
                ValueSome generated_0
            )
                value

        | Basics_Order.GT ->
            FastDict_getInner targetKey right

