let rec Graph_arrayFindBetween (lo: int64) (hi: int64) (k: 'comparable) (keyMap: Graph_Array<'comparable>) : ValueOption<int64> =
    if (>) lo hi then
        ValueNone

    else
        let mid: int64 =
            (+) lo ((/) ((-) hi lo) 2L)
        
        match Graph_arrayFind mid keyMap with
        | ValueNone ->
            ValueNone

        | ValueSome(v) ->
            match Basics_compare k v with
            | Basics_Order.LT ->
                Graph_arrayFindBetween lo ((-) mid 1L) k keyMap

            | Basics_Order.EQ ->
                (fun (generated_0: int64) ->
                    ValueSome generated_0
                )
                    mid

            | Basics_Order.GT ->
                Graph_arrayFindBetween ((+) mid 1L) hi k keyMap

let Graph_keyToVertexInArray (keyMap: Generated_ByIndex_Max<FastDict_Dict<int64, 'comparable>, int64>) (k: 'comparable) : ValueOption<int64> =
    Graph_arrayFindBetween 0L keyMap.Max k keyMap

let rec Graph_depthFirstSpanningTreeFromVerticesStep
    (graph: Graph_Graph)
    (fromVertices: List<int64>)
    (visited: FastSet_Set<Graph_Vertex>)
    (stack:
        List<
            (struct(
              Graph_Tree<Graph_Vertex>
            * List<Graph_Vertex>
            ))
            >
    )
    (soFar: List<Graph_Tree<Graph_Vertex>>)
    : List<Graph_Tree<Graph_Vertex>> =
    match fromVertices with
    | [] ->
        match stack with
        | [] ->
            List.rev soFar

        | (struct( firstTree, firstVs )) :: ((struct( secondTree, secondVs )) :: rest) ->
            Graph_depthFirstSpanningTreeFromVerticesStep graph firstVs visited (List_cons (struct( Graph_treeAddAsLastSub firstTree secondTree, secondVs )) rest) soFar

        | [ (struct( firstTree, firstVs )) ] ->
            Graph_depthFirstSpanningTreeFromVerticesStep graph firstVs visited [] (List_cons firstTree soFar)

    | fromVerticesHead :: fromVerticesTail ->
        if FastSet_member fromVerticesHead visited then
            Graph_depthFirstSpanningTreeFromVerticesStep graph fromVerticesTail visited stack soFar

        else
            Graph_depthFirstSpanningTreeFromVerticesStep graph (ValueOption.defaultValue [] (Graph_arrayFind fromVerticesHead graph)) (FastSet_insert fromVerticesHead visited) (List_cons (struct( Graph_treeOne fromVerticesHead, fromVerticesTail )) stack) soFar

let Graph_reverseEdges
    (g: Generated_ByIndex_Max<FastDict_Dict<int64, List<Graph_Vertex>>, int64>)
    : List<
        (struct(
          Graph_Vertex
        * int64
        ))
        > =
    List_foldr
        (fun (from: int64)
             (soFar:
                List<
                    (struct(
                      Graph_Vertex
                    * int64
                    ))
                    >
             ) ->
            match Graph_arrayFind from g with
            | ValueNone ->
                soFar

            | ValueSome(tos) ->
                List_foldr
                    (fun (to_: Graph_Vertex)
                         (soFarWithTos:
                            List<
                                (struct(
                                  Graph_Vertex
                                * int64
                                ))
                                >
                         ) ->
                        List_cons (struct( to_, from )) soFarWithTos
                    )
                    soFar
                    tos
        )
        []
        (Graph_vertices g)

let FastDict_fromListFast
    (assocs:
        List<
            (struct(
              'comparable
            * 'v
            ))
            >
    )
    : Internal_Dict<'comparable, 'v> =
    let rec dedupHelp
        (((struct( lastKey, _ )) as last):
            (struct(
              'comparable2
            * 'v2
            ))
        )
        (todo:
            List<
                (struct(
                  'comparable2
                * 'v2
                ))
                >
        )
        (acc:
            ListWithLength_ListWithLength<
                (struct(
                  'comparable2
                * 'v2
                ))
                >
        )
        : ListWithLength_ListWithLength<
            (struct(
              'comparable2
            * 'v2
            ))
            > =
        match todo with
        | [] ->
            ListWithLength_cons last acc

        | ((struct( todoHeadKey, _ )) as todoHead) :: todoTail ->
            let newAcc:
                    ListWithLength_ListWithLength<
                        (struct(
                          'comparable2
                        * 'v2
                        ))
                        > =
                if Basics_eq todoHeadKey lastKey then
                    acc

                else
                    ListWithLength_cons last acc
            
            dedupHelp todoHead todoTail newAcc
    let dedup
        (xs:
            List<
                (struct(
                  'comparable1
                * 'v1
                ))
                >
        )
        : ListWithLength_ListWithLength<
            (struct(
              'comparable1
            * 'v1
            ))
            > =
        match xs with
        | [] ->
            ListWithLength_empty

        | head :: tail ->
            dedupHelp head tail ListWithLength_empty
    
    Internal_fromSortedList
        (dedup
            (List_sortWith
                (fun ((struct( k1, _ )):
                        (struct(
                          'comparable
                        * 'v
                        ))
                     )
                     ((struct( k2, _ )):
                        (struct(
                          'comparable
                        * 'v
                        ))
                     ) ->
                    Basics_compare k2 k1
                )
                assocs
            )
        )

