let FastDict_merge (leftStep: 'comparable -> 'a -> 'result -> 'result) (bothStep: 'comparable -> 'a -> 'b -> 'result -> 'result) (rightStep: 'comparable -> 'b -> 'result -> 'result) (leftDict: FastDict_Dict<'comparable, 'a>) (rightDict: FastDict_Dict<'comparable, 'b>) (initialResult: 'result) : 'result =
    let rec stepState
        (rKey: 'comparable)
        (rValue: 'b)
        ((struct( list_, result )):
            (struct(
              List<
                (struct(
                  'comparable
                * 'a
                ))
                >
            * 'result
            ))
        )
        : (struct(
            List<
                (struct(
                  'comparable
                * 'a
                ))
                >
          * 'result
          )) =
        match list_ with
        | [] ->
            (struct( list_, rightStep rKey rValue result ))

        | (struct( lKey, lValue )) :: rest ->
            if (<) lKey rKey then
                stepState rKey rValue (struct( rest, leftStep lKey lValue result ))

            else
                if (>) lKey rKey then
                    (struct( list_, rightStep rKey rValue result ))

                else
                    (struct( rest, bothStep lKey lValue rValue result ))
    let ((struct( leftovers, intermediateResult )):
            (struct(
              List<
                (struct(
                  'comparable
                * 'a
                ))
                >
            * 'result
            ))
        ) =
        FastDict_foldl stepState (struct( FastDict_toList leftDict, initialResult )) rightDict
    
    List_foldl
        (fun ((struct( k, v )):
                (struct(
                  'comparable
                * 'a
                ))
             )
             (result: 'result) ->
            leftStep k v result
        )
        intermediateResult
        leftovers

