let FastDict_equals (Internal_Dict(lsz, lRoot): Internal_Dict<'comparable, 'v>) (Internal_Dict(rsz, rRoot): Internal_Dict<'comparable, 'v>) : bool =
    let rec go
        (lList:
            ValueOption<
                (struct(
                  'comparable1
                * 'v1
                * Internal_VisitQueue<'comparable1, 'v1>
                ))
                >
        )
        (rList:
            ValueOption<
                (struct(
                  'comparable1
                * 'v1
                * Internal_VisitQueue<'comparable1, 'v1>
                ))
                >
        )
        : bool =
        match lList with
        | ValueNone ->
            Basics_eq rList ValueNone

        | ValueSome((struct( lk, lv, lRest ))) ->
            match rList with
            | ValueNone ->
                false

            | ValueSome((struct( rk, rv, rRest ))) ->
                Basics_and (Basics_eq lk rk) (Basics_and (Basics_eq lv rv) (go (Internal_unconsBiggest lRest) (Internal_unconsBiggest rRest)))
    Basics_and (Basics_eq lsz rsz) (go (Internal_unconsBiggest [ lRoot ]) (Internal_unconsBiggest [ rRoot ]))

