let Graph_graphFromEdges
    (edgesUnsorted:
        List<
            (struct(
              'node
            * 'comparable
            * List<'comparable>
            ))
            >
    )
    : (struct(
        Generated_ByIndex_Max<FastDict_Dict<int64, List<Graph_Vertex>>, int64>
      * Generated_ByIndex_Max<
            FastDict_Dict<
                int64,
                (struct(
                  'node
                * 'comparable
                * List<'comparable>
                ))
                >,
            int64
            >
      )) =
    let maxVertexIndex: int64 =
        (-) (List_length edgesUnsorted) 1L
    
    let edgesSortedIndexed:
            List<
                (struct(
                  int64
                * (struct(
                    'node
                  * 'comparable
                  * List<'comparable>
                  ))
                ))
                > =
        (List_foldr
            (fun (edge:
                    (struct(
                      'node
                    * 'comparable
                    * List<'comparable>
                    ))
                 )
                 (soFar:
                    Generated_Index_Indexed<
                        int64,
                        List<
                            (struct(
                              int64
                            * (struct(
                                'node
                              * 'comparable
                              * List<'comparable>
                              ))
                            ))
                            >
                        >
                 ) ->
                { Index = (-) soFar.Index 1L
                ; Indexed = List_cons (struct( soFar.Index, edge )) soFar.Indexed
                }
            )
            { Index = maxVertexIndex
            ; Indexed = []
            }
            (List_sortWith
                (fun ((struct( _, k1, _ )):
                        (struct(
                          'node
                        * 'comparable
                        * List<'comparable>
                        ))
                     )
                     ((struct( _, k2, _ )):
                        (struct(
                          'node
                        * 'comparable
                        * List<'comparable>
                        ))
                     ) ->
                    Basics_compare k1 k2
                )
                edgesUnsorted
            )
        ).Indexed
    
    let keyMap: Graph_Array<'comparable> =
