let Graph_stronglyConnComponents
    (edges0:
        List<
            (struct(
              'node
            * 'comparable
            * List<'comparable>
            ))
            >
    )
    : List<Graph_SCC<'node>> =
    match edges0 with
    | [] ->
        []

    | _ :: _ ->
        let ((struct( graph, vertexMap )):
                (struct(
                  Graph_Graph
                * Graph_Array<
                    (struct(
                      'node
                    * 'comparable
                    * List<'comparable>
                    ))
                    >
                ))
            ) =
            Graph_graphFromEdges edges0
        
        let mentionsItself (from: int64) : bool =
            match Graph_arrayFind from graph with
            | ValueNone ->
                false

            | ValueSome(tos) ->
                List_member from tos
        
        let rec dec (node: Graph_Tree<Graph_Vertex>) (vs: List<'node>) : List<'node> =
            let treeSubsSCC: List<'node> =
                List_foldr dec vs (Graph_treeSubs node)
            
            match Graph_arrayFind (Graph_treeElement node) vertexMap with
            | ValueNone ->
                treeSubsSCC

            | ValueSome((struct( elementKeyNode, _, _ ))) ->
                List_cons elementKeyNode treeSubsSCC
        let decode (tree: Graph_Tree<Graph_Vertex>) : Graph_SCC<'node> =
            let v: Graph_Vertex =
                Graph_treeElement tree
            
            match Graph_treeSubs tree with
            | [] ->
                match Graph_arrayFind v vertexMap with
                | ValueNone ->
                    (fun (generated_0: List<'node>) ->
                        Graph_CyclicSCC generated_0
                    )
                        []

                | ValueSome((struct( vertexKeyNode, _, _ ))) ->
                    if mentionsItself v then
                        (fun (generated_0: List<'node>) ->
                            Graph_CyclicSCC generated_0
                        )
                            [ vertexKeyNode ]

                    else
                        (fun (generated_0: 'node) ->
                            Graph_AcyclicSCC generated_0
                        )
                            vertexKeyNode

            | treeSubsNotEmpty ->
                let treeSubsSCC: List<'node> =
                    List_foldr dec [] treeSubsNotEmpty
                
                (fun (generated_0: List<'node>) ->
                    Graph_CyclicSCC generated_0
                )
                    (match Graph_arrayFind v vertexMap with
                     | ValueNone ->
                        treeSubsSCC

                     | ValueSome((struct( vKeyNode, _, _ ))) ->
                        List_cons vKeyNode treeSubsSCC
                    )
        
        List.map decode (Graph_scc graph)

