let ElmWriter_writeTypeAlias (typeAlias: Generated_Documentation_Generics_Name_TypeAnnotation<ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, List<ElmSyntaxNode_Node<StringRope>>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>) : StructuredWriter_Writer =
