let ElmSyntaxTypeInfer_moduleDeclarationsToTypes (context: Generated_ModuleName_ModuleOriginLookup<StringRope, Generated_IgnoreOperatorIsExposedFromParserAdvanced_KeepOperatorIsExposedFromParserAdvanced_References_TypeConstructs<bool, bool, FastDict_Dict<StringRope, FastDict_Dict<StringRope, StringRope>>, FastDict_Dict<StringRope, FastDict_Dict<StringRope, StringRope>>>>) (declarations: List<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>) : Generated_Errors_Types<List<StringRope>, Generated_ChoiceTypes_Signatures_TypeAliases<FastDict_Dict<StringRope, Generated_Parameters_Variants<List<StringRope>, FastDict_Dict<StringRope, List<ElmSyntaxTypeInfer_Type>>>>, FastDict_Dict<StringRope, ElmSyntaxTypeInfer_Type>, FastDict_Dict<StringRope, Generated_Parameters_RecordFieldOrder_Type_<List<StringRope>, ValueOption<List<StringRope>>, ElmSyntaxTypeInfer_Type>>>> =
    let typeConstructModuleOriginLookup: FastDict_Dict<StringRope, FastDict_Dict<StringRope, StringRope>> =
        FastDict_update
            (StringRopeOne "")
            (fun (contextExposedTypeConstructsOrNothing: ValueOption<FastDict_Dict<StringRope, StringRope>>) ->
                (fun (generated_0: FastDict_Dict<StringRope, StringRope>) ->
                    ValueSome generated_0
                )
                    (List_foldl
                        (fun (ElmSyntaxNode_Node(_, declaration): ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>) (soFar: FastDict_Dict<StringRope, StringRope>) ->
                            match declaration with
                            | ElmSyntaxDeclaration_InfixDeclaration(_) ->
                                soFar

                            | ElmSyntaxDeclaration_Destructuring(_, _) ->
                                soFar

                            | ElmSyntaxDeclaration_FunctionDeclaration(_) ->
                                soFar

                            | ElmSyntaxDeclaration_PortDeclaration(_) ->
                                soFar

                            | ElmSyntaxDeclaration_AliasDeclaration(declarationTypeAlias) ->
                                FastDict_insert (ElmSyntaxNode_value declarationTypeAlias.Name) context.ModuleName soFar

                            | ElmSyntaxDeclaration_CustomTypeDeclaration(declarationChoiceType) ->
                                FastDict_insert (ElmSyntaxNode_value declarationChoiceType.Name) context.ModuleName soFar
                        )
                        (ValueOption.defaultValue FastDict_empty contextExposedTypeConstructsOrNothing)
                        declarations
                    )
            )
            context.ModuleOriginLookup.TypeConstructs
    
    List_foldl
        (fun (ElmSyntaxNode_Node(_, declaration): ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>) (soFar: Generated_Errors_Types<List<StringRope>, Generated_ChoiceTypes_Signatures_TypeAliases<FastDict_Dict<StringRope, Generated_Parameters_Variants<List<StringRope>, FastDict_Dict<StringRope, List<ElmSyntaxTypeInfer_Type>>>>, FastDict_Dict<StringRope, ElmSyntaxTypeInfer_Type>, FastDict_Dict<StringRope, Generated_Parameters_RecordFieldOrder_Type_<List<StringRope>, ValueOption<List<StringRope>>, ElmSyntaxTypeInfer_Type>>>>) ->
            match declaration with
            | ElmSyntaxDeclaration_InfixDeclaration(_) ->
                soFar

            | ElmSyntaxDeclaration_Destructuring(_, _) ->
                { Errors = List_cons (StringRopeOne "destructuring at the module level is invalid syntax") soFar.Errors
                ; Types = soFar.Types
                }

            | ElmSyntaxDeclaration_FunctionDeclaration(declarationValueOrFunction) ->
                match declarationValueOrFunction.Signature with
                | ValueNone ->
                    soFar

                | ValueSome(ElmSyntaxNode_Node(_, declarationValueOrFunctionSignature)) ->
                    match ElmSyntaxTypeInfer_syntaxToType typeConstructModuleOriginLookup declarationValueOrFunctionSignature.TypeAnnotation with
                    | Error(error) ->
                        { Errors = List_cons error soFar.Errors
                        ; Types = soFar.Types
                        }

                    | Ok(type__) ->
                        { Errors = soFar.Errors
                        ; Types =
                            { ChoiceTypes = soFar.Types.ChoiceTypes
                            ; Signatures = FastDict_insert (ElmSyntaxNode_value declarationValueOrFunctionSignature.Name) type__ soFar.Types.Signatures
                            ; TypeAliases = soFar.Types.TypeAliases
                            }
                        }

            | ElmSyntaxDeclaration_AliasDeclaration(declarationTypeAlias) ->
                match ElmSyntaxTypeInfer_syntaxToType typeConstructModuleOriginLookup declarationTypeAlias.TypeAnnotation with
                | Error(error) ->
                    { Errors = List_cons error soFar.Errors
                    ; Types = soFar.Types
                    }

                | Ok(type__) ->
                    { Errors = soFar.Errors
                    ; Types =
                        { ChoiceTypes = soFar.Types.ChoiceTypes
                        ; Signatures = soFar.Types.Signatures
                        ; TypeAliases =
                            FastDict_insert
                                (ElmSyntaxNode_value declarationTypeAlias.Name)
                                { Parameters = List.map ElmSyntaxNode_value declarationTypeAlias.Generics
                                ; RecordFieldOrder =
                                    match ElmSyntaxNode_value declarationTypeAlias.TypeAnnotation with
                                    | ElmSyntaxTypeAnnotation_Record(fields) ->
                                        (fun (generated_0: List<StringRope>) ->
                                            ValueSome generated_0
                                        )
                                            (List.map
                                                (fun (ElmSyntaxNode_Node(_, (struct( ElmSyntaxNode_Node(_, name), _ ))):
                                                        ElmSyntaxNode_Node<
                                                            (struct(
                                                              ElmSyntaxNode_Node<StringRope>
                                                            * ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>
                                                            ))
                                                            >
                                                     ) ->
                                                    name
                                                )
                                                fields
                                            )

                                    | ElmSyntaxTypeAnnotation_GenericType(_) ->
                                        ValueNone

                                    | ElmSyntaxTypeAnnotation_Typed(_, _) ->
                                        ValueNone

                                    | ElmSyntaxTypeAnnotation_Unit ->
                                        ValueNone

                                    | ElmSyntaxTypeAnnotation_Tupled(_) ->
                                        ValueNone

                                    | ElmSyntaxTypeAnnotation_GenericRecord(_, _) ->
                                        ValueNone

                                    | ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(_, _) ->
                                        ValueNone
                                ; Type_ = type__
                                }
                                soFar.Types.TypeAliases
                        }
                    }

            | ElmSyntaxDeclaration_CustomTypeDeclaration(declarationChoiceType) ->
                match
                    ElmSyntaxTypeInfer_listFoldlWhileOkFrom
                        FastDict_empty
                        (fun (ElmSyntaxNode_Node(_, variant): ElmSyntaxNode_Node<Generated_Arguments_Name<List<ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>, ElmSyntaxNode_Node<StringRope>>>) (variantsSoFar: FastDict_Dict<StringRope, List<ElmSyntaxTypeInfer_Type>>) ->
                            Result.map
                                (fun (variantValues: List<ElmSyntaxTypeInfer_Type>) ->
                                    FastDict_insert (ElmSyntaxNode_value variant.Name) variantValues variantsSoFar
                                )
                                (ElmSyntaxTypeInfer_listMapAndCombineOk
                                    (fun (variantValue: ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) ->
                                        ElmSyntaxTypeInfer_syntaxToType typeConstructModuleOriginLookup variantValue
                                    )
                                    variant.Arguments
                                )
                        )
                        declarationChoiceType.Constructors
                with
                | Error(error) ->
                    { Errors = List_cons error soFar.Errors
                    ; Types = soFar.Types
                    }

                | Ok(variants) ->
                    { Errors = soFar.Errors
                    ; Types =
                        { ChoiceTypes =
                            FastDict_insert
                                (ElmSyntaxNode_value declarationChoiceType.Name)
                                { Parameters = List.map ElmSyntaxNode_value declarationChoiceType.Generics
                                ; Variants = variants
                                }
                                soFar.Types.ChoiceTypes
                        ; Signatures = soFar.Types.Signatures
                        ; TypeAliases = soFar.Types.TypeAliases
                        }
                    }

            | ElmSyntaxDeclaration_PortDeclaration(declarationPortSignature) ->
                match ElmSyntaxTypeInfer_syntaxToType typeConstructModuleOriginLookup declarationPortSignature.TypeAnnotation with
                | Error(error) ->
                    { Errors = List_cons error soFar.Errors
                    ; Types = soFar.Types
                    }

                | Ok(type__) ->
                    { Errors = soFar.Errors
                    ; Types =
                        { ChoiceTypes = soFar.Types.ChoiceTypes
                        ; Signatures = FastDict_insert (ElmSyntaxNode_value declarationPortSignature.Name) type__ soFar.Types.Signatures
                        ; TypeAliases = soFar.Types.TypeAliases
                        }
                    }
        )
        ElmSyntaxTypeInfer_typesEmptyAndErrorsEmpty
        declarations

let ElmSyntaxTypeInfer_syntaxValueOrFunctionDeclarationRange (syntaxValueOrFunctionDeclaration: Generated_Declaration_Documentation_Signature<ElmSyntaxNode_Node<ElmSyntaxExpression_FunctionImplementation>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxSignature_Signature>>>) : Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location> =
