let ElmPackage_isBadChar (char_: int) : bool =
    Basics_or (Char_isUpper char_) (Basics_or (Basics_eq char_ 46) (Basics_eq char_ 95))

let ElmPackage_isBadProjectName (project: StringRope) : bool =
    match String_uncons project with
    | ValueNone ->
        true

    | ValueSome((struct( c, _ ))) ->
        Basics_or (String_contains (StringRopeOne "--") project) (Basics_or (String_any ElmPackage_isBadChar project) (Basics_or (String_startsWith (StringRopeOne "-") project) (not (Char_isLower c))))

let ElmPackage_fromString (string_: StringRope) : ValueOption<ElmPackage_Name> =
    match String_split (StringRopeOne "/") string_ with
    | [ author; project ] ->
        if ElmPackage_isBadProjectName project then
            ValueNone

        else
            (fun (generated_0: ElmPackage_Name) ->
                ValueSome generated_0
            )
                ((fun (generated_0: StringRope) (generated_1: StringRope) ->
                    ElmPackage_Name (struct( generated_0, generated_1 ))
                 )
                    author
                    project
                )

    | _ ->
        ValueNone

let rec ElmProject_verifyDepNames
    (revDeps:
        List<
            (struct(
              ElmPackage_Name
            * 'a
            ))
            >
    )
    (pairs:
        List<
            (struct(
              StringRope
            * 'a
            ))
            >
    )
    : JsonDecode_Decoder<
        List<
            (struct(
              ElmPackage_Name
            * 'a
            ))
            >
        > =
    match pairs with
    | [] ->
        JsonDecode_succeed (List.rev revDeps)

    | (struct( key, con )) :: otherPairs ->
        match ElmPackage_fromString key with
        | ValueSome(pkg) ->
            ElmProject_verifyDepNames (List_cons (struct( pkg, con )) revDeps) otherPairs

        | ValueNone ->
            JsonDecode_fail (String_append (StringRopeOne "\"") (String_append key (StringRopeOne "\" is not a valid package name.")))

let ElmProject_depsDecoder (constraintDecoder: JsonDecode_Decoder<'a>) : JsonDecode_Decoder<ElmProject_Deps<'a>> =
    JsonDecode_andThen (ElmProject_verifyDepNames []) (JsonDecode_keyValuePairs constraintDecoder)

