    JsonDecode_map6
        (fun (generated_Elm: ElmVersion_Version) (generated_Dirs: List<StringRope>) (generated_DepsDirect: ElmProject_Deps<ElmVersion_Version>) (generated_DepsIndirect: ElmProject_Deps<ElmVersion_Version>) (generated_TestDepsDirect: ElmProject_Deps<ElmVersion_Version>) (generated_TestDepsIndirect: ElmProject_Deps<ElmVersion_Version>) ->
            { DepsDirect = generated_DepsDirect
