            ; Dirs = generated_Dirs
            ; Elm = generated_Elm
            ; TestDepsDirect = generated_TestDepsDirect
            ; TestDepsIndirect = generated_TestDepsIndirect
            }
        )
        (JsonDecode_field (StringRopeOne "elm-version") ElmVersion_decoder)
        (JsonDecode_field (StringRopeOne "source-directories") (JsonDecode_list JsonDecode_string))
        (JsonDecode_at
            [ StringRopeOne "dependencies";
              StringRopeOne "direct"
            ]
            (ElmProject_depsDecoder ElmVersion_decoder)
        )
        (JsonDecode_at
            [ StringRopeOne "dependencies";
              StringRopeOne "indirect"
            ]
            (ElmProject_depsDecoder ElmVersion_decoder)
        )
        (JsonDecode_at
            [ StringRopeOne "test-dependencies";
              StringRopeOne "direct"
            ]
            (ElmProject_depsDecoder ElmVersion_decoder)
        )
        (JsonDecode_at
            [ StringRopeOne "test-dependencies";
              StringRopeOne "indirect"
            ]
            (ElmProject_depsDecoder ElmVersion_decoder)
