let ElmDocs_nameToBlock (docs: Generated_Aliases_Binops_Comment_Name_Unions_Values<List<ElmDocs_Alias>, List<ElmDocs_Binop>, StringRope, StringRope, List<ElmDocs_Union>, List<Generated_Comment_Name_Tipe<StringRope, StringRope, ElmType_Type>>>) (docsName: StringRope) : ElmDocs_Block =
    let name: StringRope =
        if String_startsWith (StringRopeOne "(") docsName then
            String_dropLeft 1L (String_dropRight 1L docsName)

        else
            docsName
    
    ElmDocs_find__r_Comment_Name_Tipe
        (fun (generated_0: ElmDocs_Value) ->
            ElmDocs_ValueBlock generated_0
        )
        name
        docs.Values
        (ElmDocs_find__r_Associativity_Comment_Name_Precedence_Tipe
            (fun (generated_0: ElmDocs_Binop) ->
                ElmDocs_BinopBlock generated_0
            )
            name
            docs.Binops
            (ElmDocs_find__r_Args_Comment_Name_Tags
                (fun (generated_0: ElmDocs_Union) ->
                    ElmDocs_UnionBlock generated_0
                )
                name
                docs.Unions
                (ElmDocs_find__r_Args_Comment_Name_Tipe
                    (fun (generated_0: ElmDocs_Alias) ->
                        ElmDocs_AliasBlock generated_0
                    )
                    name
                    docs.Aliases
                    ((fun (generated_0: StringRope) ->
                        ElmDocs_UnknownBlock generated_0
                     )
                        name
                    )
                )
            )
        )

let rec ElmDocs_partsToBlocks (docs: ElmDocs_Module) (parts: List<StringRope>) : List<ElmDocs_Block> =
    match parts with
    | [] ->
        []

    | part :: otherParts ->
        match String_words (String_trim part) with
        | [] ->
            [ (fun (generated_0: StringRope) ->
                ElmDocs_MarkdownBlock generated_0
              )
                (String_join (StringRopeOne ",") parts)
            ]

        | [ name ] ->
            List_cons (ElmDocs_nameToBlock docs name) (ElmDocs_partsToBlocks docs otherParts)

        | name :: _ ->
            [ ElmDocs_nameToBlock docs name;
              (fun (generated_0: StringRope) ->
                ElmDocs_MarkdownBlock generated_0
              )
                (String_join (StringRopeOne ",") (List_cons (String_dropLeft (String_length name) (String_trimLeft part)) otherParts))
            ]

