let ElmDocs_chunkToBlocks (docs: ElmDocs_Module) (chunk: StringRope) : List<ElmDocs_Block> =
    ElmDocs_partsToBlocks docs (String_split (StringRopeOne ",") chunk)

let ElmDocs_toBlocks (docs: Generated_Aliases_Binops_Comment_Name_Unions_Values<List<ElmDocs_Alias>, List<ElmDocs_Binop>, StringRope, StringRope, List<ElmDocs_Union>, List<ElmDocs_Value>>) : List<ElmDocs_Block> =
    match String_split (StringRopeOne "\n@docs ") docs.Comment with
    | [] ->
        []

    | firstMarkdown :: docsChunks ->
        List_cons
            ((fun (generated_0: StringRope) ->
                ElmDocs_MarkdownBlock generated_0
             )
                firstMarkdown
            )
            (List.collect (ElmDocs_chunkToBlocks docs) docsChunks)

let ElmDocs_assocDecoder: JsonDecode_Decoder<ElmDocs_Associativity> =
    JsonDecode_andThen ElmDocs_toAssoc JsonDecode_string

let ElmDocs_binopDecoder: JsonDecode_Decoder<ElmDocs_Binop> =
    JsonDecode_map5
        (fun (generated_Name: StringRope) (generated_Comment: StringRope) (generated_Tipe: ElmType_Type) (generated_Associativity: ElmDocs_Associativity) (generated_Precedence: int64) ->
            { Associativity = generated_Associativity
            ; Comment = generated_Comment
            ; Name = generated_Name
            ; Precedence = generated_Precedence
            ; Tipe = generated_Tipe
            }
        )
        (JsonDecode_field (StringRopeOne "name") JsonDecode_string)
        (JsonDecode_field (StringRopeOne "comment") JsonDecode_string)
        (JsonDecode_field (StringRopeOne "type") ElmType_decoder)
        (JsonDecode_field (StringRopeOne "associativity") ElmDocs_assocDecoder)
        (JsonDecode_field (StringRopeOne "precedence") JsonDecode_int)

let ElmDocs_aliasDecoder: JsonDecode_Decoder<ElmDocs_Alias> =
    JsonDecode_map4
        (fun (generated_Name: StringRope) (generated_Comment: StringRope) (generated_Args: List<StringRope>) (generated_Tipe: ElmType_Type) ->
            { Args = generated_Args
            ; Comment = generated_Comment
            ; Name = generated_Name
            ; Tipe = generated_Tipe
            }
        )
        (JsonDecode_field (StringRopeOne "name") JsonDecode_string)
        (JsonDecode_field (StringRopeOne "comment") JsonDecode_string)
        (JsonDecode_field (StringRopeOne "args") (JsonDecode_list JsonDecode_string))
        (JsonDecode_field (StringRopeOne "type") ElmType_decoder)

let ElmDocs_decoder: JsonDecode_Decoder<ElmDocs_Module> =
    JsonDecode_map6
        (fun (generated_Name: StringRope) (generated_Comment: StringRope) (generated_Unions: List<ElmDocs_Union>) (generated_Aliases: List<ElmDocs_Alias>) (generated_Values: List<ElmDocs_Value>) (generated_Binops: List<ElmDocs_Binop>) ->
            { Aliases = generated_Aliases
            ; Binops = generated_Binops
            ; Comment = generated_Comment
            ; Name = generated_Name
            ; Unions = generated_Unions
            ; Values = generated_Values
            }
        )
        (JsonDecode_field (StringRopeOne "name") JsonDecode_string)
        (JsonDecode_field (StringRopeOne "comment") JsonDecode_string)
        (JsonDecode_field (StringRopeOne "unions") (JsonDecode_list ElmDocs_unionDecoder))
        (JsonDecode_field (StringRopeOne "aliases") (JsonDecode_list ElmDocs_aliasDecoder))
        (JsonDecode_field (StringRopeOne "values") (JsonDecode_list ElmDocs_valueDecoder))
        (JsonDecode_field (StringRopeOne "binops") (JsonDecode_list ElmDocs_binopDecoder))

let ElmConstraint_opToString (op: ElmConstraint_Op) : StringRope =
    match op with
    | ElmConstraint_LessThan ->
        StringRopeOne " < "

    | ElmConstraint_LessOrEq ->
        StringRopeOne " <= "

let ElmConstraint_toString (ElmConstraint_Constraint(lower, lop, uop, upper): ElmConstraint_Constraint) : StringRope =
    String_append (ElmVersion_toString lower) (String_append (ElmConstraint_opToString lop) (String_append (StringRopeOne "v") (String_append (ElmConstraint_opToString uop) (ElmVersion_toString upper))))

let ElmConstraint_opFromString (op: StringRope) : ValueOption<ElmConstraint_Op> =
    match op with
    | StringRopeOne("<") ->
        (fun (generated_0: ElmConstraint_Op) ->
            ValueSome generated_0
        )
            ElmConstraint_LessThan

    | StringRopeOne("<=") ->
        (fun (generated_0: ElmConstraint_Op) ->
            ValueSome generated_0
        )
            ElmConstraint_LessOrEq

    | _ ->
        ValueNone

let ElmConstraint_encode (constraint_: ElmConstraint_Constraint) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_string (ElmConstraint_toString constraint_)

let ElmProject_encode (project: ElmProject_Project) : System.Text.Json.Nodes.JsonNode =
    match project with
    | ElmProject_Application({ DepsDirect = depsDirect; DepsIndirect = depsIndirect; Dirs = dirs; Elm = elm; TestDepsDirect = testDepsDirect; TestDepsIndirect = testDepsIndirect }) ->
        JsonEncode_object
            [ (struct( StringRopeOne "type", JsonEncode_string (StringRopeOne "application") ));
              (struct( StringRopeOne "source-directories", JsonEncode_list JsonEncode_string dirs ));
              (struct( StringRopeOne "elm-version", ElmVersion_encode elm ));
              (struct(
                StringRopeOne "dependencies"
              , JsonEncode_object
                    [ (struct( StringRopeOne "direct", ElmProject_encodeDeps ElmVersion_encode depsDirect ));
                      (struct( StringRopeOne "indirect", ElmProject_encodeDeps ElmVersion_encode depsIndirect ))
                    ]
              ));
              (struct(
                StringRopeOne "test-dependencies"
              , JsonEncode_object
                    [ (struct( StringRopeOne "direct", ElmProject_encodeDeps ElmVersion_encode testDepsDirect ));
                      (struct( StringRopeOne "indirect", ElmProject_encodeDeps ElmVersion_encode testDepsIndirect ))
                    ]
              ))
            ]

    | ElmProject_Package({ Deps = deps; Elm = elm; Exposed = exposed; License = license; Name = name; Summary = summary; TestDeps = testDeps; Version = version }) ->
        JsonEncode_object
            [ (struct( StringRopeOne "type", JsonEncode_string (StringRopeOne "package") ));
              (struct( StringRopeOne "name", ElmPackage_encode name ));
              (struct( StringRopeOne "summary", JsonEncode_string summary ));
              (struct( StringRopeOne "license", ElmLicense_encode license ));
              (struct( StringRopeOne "version", ElmVersion_encode version ));
              (struct( StringRopeOne "exposed-modules", ElmProject_encodeExposed exposed ));
              (struct( StringRopeOne "elm-version", ElmConstraint_encode elm ));
              (struct( StringRopeOne "dependencies", ElmProject_encodeDeps ElmConstraint_encode deps ));
              (struct( StringRopeOne "test-dependencies", ElmProject_encodeDeps ElmConstraint_encode testDeps ))
            ]

let ElmConstraint_checkOp (op: ElmConstraint_Op) (v1: ElmVersion_Version) (v2: ElmVersion_Version) : bool =
    match ElmVersion_compare v1 v2 with
    | Basics_Order.LT ->
        true

    | Basics_Order.EQ ->
        match op with
        | ElmConstraint_LessThan ->
            false

        | ElmConstraint_LessOrEq ->
            true

    | Basics_Order.GT ->
        false

let ElmConstraint_checkConstraint ((ElmConstraint_Constraint(lower, _, _, upper) as constraint_): ElmConstraint_Constraint) : ValueOption<ElmConstraint_Constraint> =
    match ElmVersion_compare lower upper with
