let ElmProjectToSwift_fromModuleSources (originalSources: List<StringRope>) : Result_Result<StringRope, StringRope> =
    match
        ElmProjectToSwift_listFoldlWhileOkFrom
            []
            (fun (originalModuleSource: StringRope) (soFar: List<ElmSyntaxFile_File>) ->
                match ElmParser_parseToFile originalModuleSource with
                | Error(_) ->
                    (fun (generated_0: StringRope) ->
                        Error generated_0
                    )
                        originalModuleSource

                | Ok(syntaxModule) ->
                    (fun (generated_0: List<ElmSyntaxFile_File>) ->
                        Ok generated_0
                    )
                        (List_cons syntaxModule soFar)
            )
            originalSources
    with
    | Error(source) ->
        (fun (generated_0: StringRope) ->
            Error generated_0
        )
            (String_append (StringRopeOne "source couldn't be parsed. Check for compiler errors. Here's the start of the module:\n") (String_left 50L source))

    | Ok(parsedModules) ->
        let transpiledDeclarationsAndErrors: Generated_Declarations_Errors<Generated_ChoiceTypes_RecordTypes_TypeAliases_ValuesAndFunctions<FastDict_Dict<StringRope, Generated_Parameters_Variants<List<StringRope>, FastDict_Dict<StringRope, ValueOption<ElmSyntaxToSwift_SwiftType>>>>, FastSet_Set<List<StringRope>>, FastDict_Dict<StringRope, Generated_Parameters_Type_<List<StringRope>, ElmSyntaxToSwift_SwiftType>>, FastDict_Dict<StringRope, Generated_Parameters_Result_ResultType<List<Generated_Pattern_Type_<ElmSyntaxToSwift_SwiftPattern, ElmSyntaxToSwift_SwiftType>>, ElmSyntaxToSwift_SwiftExpression, ElmSyntaxToSwift_SwiftType>>>, List<StringRope>> =
            ElmSyntaxToSwift_modules parsedModules
        
        match transpiledDeclarationsAndErrors.Errors with
        | error0 :: error1Up ->
            (fun (generated_0: StringRope) ->
                Error generated_0
            )
                (String_join (StringRopeOne "\n") (List_cons error0 error1Up))

        | [] ->
            (fun (generated_0: StringRope) ->
                Ok generated_0
            )
                (String_replace (StringRopeOne "ListExtra_unique<'a>") (StringRopeOne "ListExtra_unique<'a when 'a: equality>") (String_replace (StringRopeOne "ListExtra_uniqueHelp<'a>") (StringRopeOne "ListExtra_uniqueHelp<'a when 'a: equality>") (ElmSyntaxToSwift_swiftDeclarationsToModuleString transpiledDeclarationsAndErrors.Declarations)))


